#include "elevsim.h"
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include <errno.h>
#include <math.h>
void es_error(EsError*e,int code,int line,const char*fmt,...){if(!e||e->code)return;e->code=code;e->line=line;va_list ap;va_start(ap,fmt);vsnprintf(e->msg,sizeof e->msg,fmt,ap);va_end(ap);}
void*es_malloc(size_t n,EsError*e){if(!n)n=1;void*p=malloc(n);if(!p)es_error(e,8,0,"allocation failed");return p;}void*es_calloc(size_t n,size_t s,EsError*e){if(s&&n>SIZE_MAX/s){es_error(e,8,0,"allocation overflow");return NULL;}void*p=calloc(n?n:1,s?s:1);if(!p)es_error(e,8,0,"allocation failed");return p;}void*es_realloc(void*p,size_t n,EsError*e){if(!n)n=1;void*q=realloc(p,n);if(!q)es_error(e,8,0,"allocation failed");return q;}char*es_strdup(const char*s,EsError*e){size_t n=strlen(s);char*p=es_malloc(n+1,e);if(p)memcpy(p,s,n+1);return p;}char*es_strndup(const char*s,size_t n,EsError*e){char*p=es_malloc(n+1,e);if(p){memcpy(p,s,n);p[n]=0;}return p;}
bool es_utf8_valid(const unsigned char*s,size_t n,bool reject_nul){for(size_t i=0;i<n;){unsigned c=s[i++];if(c==0&&reject_nul)return false;if(c<0x80)continue;unsigned need;uint32_t cp;if(c>=0xc2&&c<=0xdf){need=1;cp=c&31;}else if(c>=0xe0&&c<=0xef){need=2;cp=c&15;}else if(c>=0xf0&&c<=0xf4){need=3;cp=c&7;}else return false;if(i+need>n)return false;for(unsigned k=0;k<need;k++){unsigned q=s[i++];if((q&0xc0)!=0x80)return false;cp=(cp<<6)|(q&63);}if((need==2&&cp<0x800)||(need==3&&cp<0x10000)||cp>0x10ffff||(cp>=0xd800&&cp<=0xdfff))return false;}return true;}
bool es_read_file(const char*path,unsigned char**out,size_t*n,EsError*e,int ec){*out=NULL;*n=0;FILE*f=fopen(path,"rb");if(!f){es_error(e,ec,0,"cannot open '%s': %s",path,strerror(errno));return false;}size_t cap=8192,len=0;unsigned char*b=es_malloc(cap+1,e);if(!b){fclose(f);return false;}for(;;){if(len==cap){if(cap>SIZE_MAX/2-1){free(b);fclose(f);es_error(e,8,0,"input too large");return false;}cap*=2;unsigned char*q=es_realloc(b,cap+1,e);if(!q){free(b);fclose(f);return false;}b=q;}size_t got=fread(b+len,1,cap-len,f);len+=got;if(got==0){if(ferror(f)){free(b);fclose(f);es_error(e,ec,0,"read error '%s'",path);return false;}break;}}if(fclose(f)){free(b);es_error(e,ec,0,"close error '%s'",path);return false;}b[len]=0;*out=b;*n=len;return true;}
bool es_write_all(FILE*f,const void*p,size_t n){return fwrite(p,1,n,f)==n&&!ferror(f);}uint64_t es_fnv1a64(const unsigned char*p,size_t n){uint64_t h=UINT64_C(14695981039346656037);for(size_t i=0;i<n;i++){h^=p[i];h*=UINT64_C(1099511628211);}return h;}uint64_t es_ceil_div_u64(uint64_t a,uint64_t b){return a/b+(a%b!=0);}double es_floor_pos(int f,double h){return (f-1)*h;}bool es_nearly_equal(double a,double b){return fabs(a-b)<=1e-9*fmax(1.0,fmax(fabs(a),fabs(b)));}
void es_json_write_string(FILE*f,const char*s){fputc('"',f);for(const unsigned char*p=(const unsigned char*)s;*p;p++){switch(*p){case '"':fputs("\\\"",f);break;case '\\':fputs("\\\\",f);break;case '\b':fputs("\\b",f);break;case '\f':fputs("\\f",f);break;case '\n':fputs("\\n",f);break;case '\r':fputs("\\r",f);break;case '\t':fputs("\\t",f);break;default:if(*p<0x20)fprintf(f,"\\u%04x",*p);else fputc(*p,f);}}fputc('"',f);}void es_csv_field(FILE*f,const char*s){bool q=false;for(const char*p=s;*p;p++)if(*p==','||*p=='"'||*p=='\r'||*p=='\n')q=true;if(!q){fputs(s,f);return;}fputc('"',f);for(const char*p=s;*p;p++){if(*p=='"')fputc('"',f);fputc(*p,f);}fputc('"',f);}
Value*value_new(VType t,int line,EsError*e){Value*v=es_calloc(1,sizeof*v,e);if(v){v->type=t;v->line=line;}return v;}void value_free(Value*v){if(!v)return;if(v->type==V_INT||v->type==V_STR)free(v->u.s);else if(v->type==V_ARR){for(size_t i=0;i<v->u.arr.n;i++)value_free(v->u.arr.v[i]);free(v->u.arr.v);}else if(v->type==V_OBJ){for(size_t i=0;i<v->u.obj.n;i++){free(v->u.obj.v[i].key);value_free(v->u.obj.v[i].val);}free(v->u.obj.v);}free(v);}Value*obj_get(const Value*o,const char*k){if(!o||o->type!=V_OBJ)return NULL;for(size_t i=0;i<o->u.obj.n;i++)if(!strcmp(o->u.obj.v[i].key,k))return o->u.obj.v[i].val;return NULL;}bool obj_has(const Value*o,const char*k){return obj_get(o,k)!=NULL;}
double es_motion_profile(double vmax,double a,double d,double D,double*ta,double*tc,double*td,double*vp){double da=vmax*vmax/(2*a),dd=vmax*vmax/(2*d);if(D>=da+dd){*vp=vmax;*ta=vmax/a;*tc=(D-da-dd)/vmax;*td=vmax/d;}else{*vp=sqrt((2*D*a*d)/(a+d));*ta=*vp/a;*tc=0;*td=*vp/d;}return *ta+*tc+*td;}
